}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Name : string
  + Price : double
}

class StayType {
  + Name : string
}

class Inhabitant {
  + Name : string
  + IdentificationData : string
}

class Registration {
  + RegistrationDate : date
}

class Assessment {
  + NeedsHelp : boolean
  + ResultingStayType : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Status : string
  + ProposalDate : date
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class Stay {
  + StartDate : date
  + IsSuspended : boolean
  + Discount : double
}

class RestHome {}
class RestNursingHome {}
class ServiceFlat {}

StayType "1" -- "1" RestHome
